<template><view class="page"><view class="head"><text class="eyebrow">AI CREATIVE STUDIO</text><text class="title">{{ title }}</text><text class="cost">本次生成将消耗 {{ cost }} 积分</text></view><view class="card"><text class="label">作品名称</text><input v-model="form.title" placeholder="给作品起一个名字" class="input"/><text class="label">创作描述</text><textarea v-model="form.prompt" placeholder="描述主题、材质、纹样、色彩与使用场景…" class="textarea" maxlength="800"/><template v-if="mode==='image3d'"><text class="label">参考图片</text><button class="secondary" @tap="pickImage">{{ referencePath ? '已选择图片，点击更换' : '选择一张图片' }}</button></template><view class="notice"><text>提示：</text>{{ mode==='image'?'文字生成图片将生成文创视觉作品。':mode==='text3d'?'请尽量描述模型主体、材质和结构。':'上传清晰、主体完整的参考图可获得更好效果。' }}</view><button class="generate" :loading="loading" @tap="generate">{{ loading ? '正在生成，请稍候…' : `开始生成（${cost} 积分）` }}</button></view></view></template>
<script setup lang="ts">import { computed, ref } from 'vue';import { onLoad } from '@dcloudio/uni-app';import { createImage, createModel, uploadReference } from '../../api/creative';import { requireSession } from '../../utils/session';const mode=ref<'image'|'text3d'|'image3d'>('image');const form=ref({title:'',prompt:''});const loading=ref(false);const referencePath=ref('');const title=computed(()=>mode.value==='image'?'文字生成图片':mode.value==='text3d'?'文字生成 3D':'图片生成 3D');const cost=computed(()=>mode.value==='image'?16:mode.value==='text3d'?60:70);onLoad((q:any)=>{if(q.mode)mode.value=q.mode});function pickImage(){uni.chooseImage({count:1,sizeType:['compressed'],success:r=>referencePath.value=r.tempFilePaths[0]})}async function generate(){if(!requireSession())return;if(!form.value.prompt.trim())return uni.showToast({title:'请填写创作描述',icon:'none'});if(mode.value==='image3d'&&!referencePath.value)return uni.showToast({title:'请先选择参考图片',icon:'none'});loading.value=true;try{let result:any;if(mode.value==='image')result=await createImage({title:form.value.title,prompt:form.value.prompt,scene:'文创产品',productType:'文创产品'});else {let inputAssetId:any; if(mode.value==='image3d')inputAssetId=(await uploadReference(referencePath.value)).assetId;result=await createModel({title:form.value.title,prompt:form.value.prompt,mode:mode.value==='image3d'?'image_to_model':'text_to_model',inputAssetId,promptTemplate:'cultural_product'})}uni.showModal({title:'已提交创作',content:`${mode.value==='image'?'作品已生成':'3D 生成任务已创建'}，可在“我的作品”中查看进度。`,showCancel:false,success:()=>uni.navigateTo({url:'/pages/works/index'})})}catch(e:any){uni.showToast({title:e.message||'生成失败',icon:'none'})}finally{loading.value=false}}</script>
<style scoped lang="scss">.page{min-height:100vh}.head{padding:50rpx 38rpx 38rpx;background:linear-gradient(140deg,#fff0df,#f5d1b5)}.eyebrow{font-size:20rpx;color:#a64b2b;letter-spacing:3rpx}.title{display:block;font-size:48rpx;font-weight:800;margin-top:18rpx}.cost{display:block;margin-top:10rpx;font-size:25rpx;color:#8c472e}.card{margin:28rpx;padding:32rpx;background:#fff;border-radius:28rpx}.label{font-size:27rpx;font-weight:700;display:block;margin:16rpx 0}.input,.textarea{box-sizing:border-box;width:100%;background:#faf5f1;border-radius:16rpx;padding:24rpx;font-size:27rpx}.input{height:88rpx}.textarea{height:250rpx}.secondary{height:82rpx;line-height:82rpx;border-radius:14rpx;background:#f7e5d8;color:#863c24;font-size:26rpx}.notice{padding:22rpx;background:#fff6ec;border-radius:16rpx;color:#8b6555;font-size:23rpx;line-height:1.65;margin-top:28rpx}.generate{height:96rpx;line-height:96rpx;margin-top:32rpx;background:#963c23;color:#fff;border-radius:48rpx;font-size:29rpx}</style>
